import{d as g,C as n,o as h,c as p,E as o,a3 as a}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"涣卦","description":"第五十九卦·风水涣——风行水上，涣。涣是离散、疏解：既散其所当散（隔阂、私党、僵固的依附），也聚其所当聚（人心、共同方向、秩序）。散与聚并不相反，先散掉阻碍，才能重新凝聚。","frontmatter":{"title":"涣卦","description":"第五十九卦·风水涣——风行水上，涣。涣是离散、疏解：既散其所当散（隔阂、私党、僵固的依附），也聚其所当聚（人心、共同方向、秩序）。散与聚并不相反，先散掉阻碍，才能重新凝聚。","category":"hexagram","aliases":["涣","风水涣","涣卦"],"source":["《周易》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/hexagrams/59-fengshuihuan.md","filePath":"yijing/hexagrams/59-fengshuihuan.md","lastUpdated":1792641266000}'),d={name:"yijing/hexagrams/59-fengshuihuan.md"},x=g({...d,setup(u){const e=[{id:"huan",term:"涣",pinyin:"huàn",meaning:"离散、散开、疏解。既指涣散之势，也指主动疏解的动作。",context:"全卦六爻，五个「涣」字各有对象：涣其躬（自身）、涣其群（私党）、涣汗其大号（号令）、涣王居（居积）、涣其血（伤害）。"},{id:"zheng",term:"拯",pinyin:"zhěng",meaning:"拯救、救助。",context:"「用拯马壮」：在已经出现的涣散处境中及时借力救济。"},{id:"mazhuang",term:"马壮",pinyin:"mǎ zhuàng",meaning:"强壮的马，象征足以承担救援、行动的力量。",context:"初六阴柔、自身力量有限，故须借强健之力——小象「顺也」，正指它顺承九二。"},{id:"ji",term:"机",pinyin:"jī",meaning:"几案一类可以凭依、支撑的器物。非现代语「机会」「机关」。",context:"「涣奔其机」：涣散之时迅速奔向能安顿、支撑自己的凭依，原有之悔由此消除。"},{id:"gong",term:"躬",pinyin:"gōng",meaning:"自身、自己。",context:"「涣其躬」：散去自身之私，不再以己身为唯一中心——非指消解身体。小象「志在外也」表明志向不局限于自身。"},{id:"qun",term:"群",pinyin:"qún",meaning:"群体、朋党、局部结党。",context:"「涣其群」：散去局部私党。与下句「涣有丘」连读，义为散小群而成大聚。"},{id:"qiu",term:"丘",pinyin:"qiū",meaning:"土丘；传统亦借其聚积、高大之象为解。",context:"「涣有丘」：散掉小群的边界，反而聚成更大的共同体。小象「光大也」正与此呼应。"},{id:"yi",term:"夷",pinyin:"yí",meaning:"平常、常人。不宜只按「平坦」理解。",context:"「匪夷所思」：这不是寻常思虑所能想到的——散小群而成大聚，超出一般人的直观。"},{id:"han",term:"汗",pinyin:"hàn",meaning:"汗液散出之象。",context:"「涣汗其大号」：以汗出疏解病患，喻君王发布足以通达众人的大号令。亦有注家强调号令如汗，既出不宜轻易反复。"},{id:"dahao",term:"大号",pinyin:"dà hào",meaning:"重大的号令。",context:"涣散之时，号令的功能是通达众人、疏解困局，而非宣示威权。"},{id:"wangju",term:"王居",pinyin:"wáng jū",meaning:"王者之居处；亦有注家将「居」解为居积、积聚（散王者之积以济众）。",context:"两种解释并存，不宜只取一说。小象「王居无咎，正位也」，至少表明九五之无咎与「正位」相关。"},{id:"xue",term:"血",pinyin:"xuè",meaning:"流血、伤害。",context:"「涣其血」：使流血伤害得以消解。小象「远害也」给出明确方向——不是伤害身体、耗损气血。"},{id:"ti",term:"逖",pinyin:"tì",meaning:"远。",context:"「去逖出」：离开、远离、脱出。重点是远害，不是「远处潜伏的忧患」（此说缺乏字义依据）。"}],r=[{position:"初六",type:"yin",text:"用拯马壮，吉。",xiang:"初六之吉，顺也。",textModern:"涣散初起，及时借助强健的力量救济，可以获得吉利。初六阴柔，自身力量有限，小象「顺也」正指它顺承九二——所借之力是否合适，是这一爻的关键。",xiangModern:"初六之所以吉，在于它柔顺而能顺承有力者。"},{position:"九二",type:"yang",text:"涣奔其机，悔亡。",xiang:"涣奔其机，得愿也。",textModern:"涣散之时，迅速奔向可以安顿、支撑自己的凭依（机为几案一类可倚之物），原有的悔恨因此消除。形态开始散乱时，不追逐所有波动，而是直奔真正的着力点。",xiangModern:"涣散中奔向可倚之处，因而得以遂其心愿。"},{position:"六三",type:"yin",text:"涣其躬，无悔。",xiang:"涣其躬，志在外也。",textModern:"散去自身之私，不再以己身为唯一中心，因而无悔。六三阴爻居阳位、本不当位，小象「志在外也」表明它的志向不局限于自身——不是毁弃身体，而是不再把身体感受、自我形象和个人立场当作唯一中心。",xiangModern:"散去自身之私，是因为心志朝向外部。"},{position:"六四",type:"yin",text:"涣其群，元吉。涣有丘，匪夷所思。",xiang:"涣其群元吉，光大也。",textModern:"散去局部私党，反而形成更大范围的凝聚，大吉。散掉小群的边界，才可能聚成更大的共同体——这不是寻常思虑所能想到的。「群」指朋党、局部结党，重点不在否定一切群体，而在不让局部利益与群体身份限制判断。",xiangModern:"散去私党而大吉，因为其气象光明广大。"},{position:"九五",type:"yang",text:"涣汗其大号，涣王居，无咎。",xiang:"王居无咎，正位也。",textModern:"在涣散之时发布足以通达众人、疏解困局的重大号令（如汗之散出，一经发出不宜反复）；散出王者所居积之物以济众，因而无咎。这是全卦解释分歧最大的一爻：「涣王居」有「散其居积」与「王者居位以治涣」两说，不宜只取一说；小象「正位也」至少表明其无咎与正位相关。",xiangModern:"王居而无咎，因为他居于正当之位。"},{position:"上九",type:"yang",text:"涣其血，去逖出，无咎。",xiang:"涣其血，远害也。",textModern:"使流血伤害得以消解，远离危险、脱出伤害的处境，所以无咎。小象「远害也」把方向说得很清楚：逖是「远」，重点在离开伤害。「无咎」不是无条件保证一切圆满——是因为能远害，所以无咎。",xiangModern:"涣其血，是说远远地离开祸害。"}];return(m,t)=>{const i=n("DaoHexagramViewer"),s=n("DaoHexagramYaoCards"),l=n("DaoKeywordCards");return h(),p("div",null,[o(i,{name:"涣",fullName:"风水涣",upper:"☴",lower:"☵",guaCi:"涣，亨。王假有庙。利涉大川，利贞。",pinyin:["huàn"],element:"火",direction:"南",insight:"风行水上，水波展开，原来集中的形态发生变化——这是「涣」的直观入口。但涣卦不只说「东西散了」，它追问的是：已经离散的局面，如何化解危险、重新获得共同方向？散其所当散，聚其所当聚。",guaSlug:"59fengshuihuan",lines:r}),t[0]||(t[0]=a("",10)),o(s,{element:"火",guaSlug:"59fengshuihuan",glossary:e,items:r}),t[1]||(t[1]=a("",35)),o(l,{title:"字词释义",items:[{term:"涣",pinyin:["huàn"],meaning:"离散、散开、疏解。既是涣散之势，也是主动疏解的动作——全卦五个「涣」字，对象各不相同：涣其躬（自身）、涣其群（私党）、涣汗其大号（号令）、涣王居（居积）、涣其血（伤害）。"},{term:"假",pinyin:["jiǎ"],meaning:"至、到达。「王假有庙」谓君王来到宗庙，以共同仪式联结众人，提供共同的精神归属。"},{term:"有庙",pinyin:["yǒu","miào"],meaning:"宗庙。大象「先王以享于帝立庙」同此：涣散之时，需要一个能超越个体分歧的共同中心。"},{term:"刚来而不穷",pinyin:["gāng","lái"],meaning:"阳刚（九二）来居下卦而不至困穷。身处坎险之中而有力，是涣而可解的前提。"},{term:"柔得位乎外而上同",pinyin:["róu","dé","wèi"],meaning:"六四以柔居阴位而在于外卦，上顺九五。下有位、上有应——「涣而能聚」的结构基础。"},{term:"王乃在中",pinyin:["wáng","nǎi"],meaning:"九五居中得正。彖传释「王假有庙」：共同中心必须居于正中，而非偏于一方。"},{term:"乘木有功",pinyin:["chéng","mù"],meaning:"巽为木、坎为水，乘木渡水之象。喻涣散之中仍可行动，但须有合适的凭借与共同的方向。"},{term:"享于帝立庙",pinyin:["xiǎng","yú","dì"],meaning:"祭祀上帝、建立宗庙。大象所示：从「形散」走向「神聚」——涣的落点不在散，而在散后如何重新凝聚。"},{term:"机",pinyin:["jī"],meaning:"几案一类可以凭依、支撑的器物。非现代语的「机会」「机关」。「涣奔其机」谓奔向可靠支点。"},{term:"躬",pinyin:["gōng"],meaning:"自身、自己。「涣其躬」谓散去自身之私，不为自己之身所囿——非指消解身体。"},{term:"群 · 丘",pinyin:["qún","qiū"],meaning:"群为朋党、局部结党；丘为土丘，亦借聚积之象。「涣其群……涣有丘」两句合读：散掉小群的边界，才可能聚成更大的共同体。"},{term:"匪夷所思",pinyin:["fěi","yí","suǒ","sī"],meaning:"夷训「平常、常人」——不是寻常思虑所能想到的。指「散小群而成大聚」超出一般人的直观。"},{term:"涣汗其大号",pinyin:["huàn","hàn"],meaning:"以汗出疏解病患，喻君王发布足以通达众人、疏解困局的号令；亦强调号令如汗，既出不宜轻易反复。"},{term:"王居",pinyin:["wáng","jū"],meaning:"王者之居处；亦有注家解「居」为居积，谓散王者所积以济众。两说并存，不宜只取一说。象曰「王居无咎，正位也」，至少表明其无咎与正位相关。"},{term:"逖",pinyin:["tì"],meaning:"远。「去逖出」即离开、远离、脱出——重点是远害，不是「远处潜伏的忧患」。"},{term:"利贞",pinyin:["lì","zhēn"],meaning:"疏解和变动仍须守正。不能把「涣」理解成任意拆解、无限放弃，或「越散越好」。"},{term:"节",pinyin:["jié"],meaning:"节度、边界、秩序。涣的覆卦，也是序卦中紧随涣之后的下一卦：物不可以终离，散开之后还需要节度。"}]}),t[2]||(t[2]=a("",50))])}}});export{b as __pageData,x as default};
